'use strict';
const COURSES=[
 {id:'foundations',name:'Number sense',level:'Middle school',description:'Signed numbers, fractions, decimals, factors and powers.'},
 {id:'ratios',name:'Ratios & percents',level:'Middle school',description:'Rates, proportions, scale, percent change and interest.'},
 {id:'prealgebra',name:'Pre-algebra',level:'Middle school',description:'Expressions, equations, inequalities and coordinates.'},
 {id:'algebra1',name:'Algebra I',level:'High school',description:'Lines, systems, functions and quadratics.'},
 {id:'geometry',name:'Geometry',level:'Middle & high school',description:'Measurement, angles, similarity, transformations and solids.'},
 {id:'algebra2',name:'Algebra II',level:'High school',description:'Polynomial structure, radicals, exponential and logarithmic functions.'},
 {id:'trig',name:'Trigonometry',level:'High school',description:'Right triangles, the unit circle, periodic graphs and vectors.'},
 {id:'stats',name:'Statistics & probability',level:'Middle & high school',description:'Data, variation, chance, association and conditional probability.'},
 {id:'advanced',name:'Advanced explorations',level:'Advanced high school',description:'Sequences, complex numbers, limits and introductory calculus.'}
];
const LESSONS=[];
const fmt=n=>!Number.isFinite(n)?'undefined':Math.abs(n)>0&&Math.abs(n)<.0001?String(Number(n.toPrecision(5))):String(Number((Math.abs(n)<1e-12?0:n).toFixed(4)));
const gcd=(a,b)=>{a=Math.abs(a);b=Math.abs(b);while(b){[a,b]=[b,a%b];}return a;};
const frac=(a,b)=>{const d=gcd(a,b);return b/d===1?String(a/d):`${a/d}/${b/d}`;};
const rad=d=>d*Math.PI/180;
const range=(n,fn=i=>i)=>Array.from({length:n},(_,i)=>fn(i));
const inp=(key,label,min,max,value,step=1)=>({key,label,min,max,value,step});
const A=(min=1,max=12,value=4,label='First value')=>inp('a',label,min,max,value);
const B=(min=1,max=12,value=3,label='Second value')=>inp('b',label,min,max,value);
const C=(min=1,max=12,value=5,label='Third value')=>inp('c',label,min,max,value);
function define(id,title,course,goal,prereq,inputs,why,model){LESSONS.push({id,title,course,goal,prereq,inputs,why,model});}
function result(equation,answer,question,steps,diagram,caption,note=''){
 return {equation,answer,question,steps,diagram,caption,note,hint:steps[0],tolerance:Math.abs(answer)>0&&Math.abs(answer)<.01?Math.max(1e-12,Math.abs(answer)*1e-4):.0051};
}
const lineDiagram=(a,b,end,mode='add')=>({type:'numberline',a,b,end,mode});
const graphDiagram=(functions,domain=[-6,6],bounds=[-6,6],points=[])=>({type:'graph',functions,domain,bounds,points});
const shapeDiagram=(kind,values)=>({type:'shape',kind,...values});

define('integer-addition','Add signed numbers','foundations','Use direction and distance to add positive and negative numbers.','Counting and the number line',[A(-10,10,-3,'Starting number'),B(-10,10,7,'Number to add')],
 'Adding a positive number moves right; adding a negative number moves left. The endpoint is the sum.',p=>result(`${p.a} + (${p.b}) = ${p.a+p.b}`,p.a+p.b,`What is ${p.a} + (${p.b})?`,[`Start at ${p.a} on the number line.`,`Move ${Math.abs(p.b)} units ${p.b<0?'left':'right'} because the added number is ${p.b<0?'negative':'nonnegative'}.`,`The endpoint is ${p.a+p.b}.`],lineDiagram(p.a,p.b,p.a+p.b),'The green point is the start; the orange point is the endpoint.'));
define('integer-subtraction','Subtract signed numbers','foundations','Rewrite subtraction as adding the opposite.','Signed-number addition',[A(-10,10,4,'Starting number'),B(-10,10,-3,'Number to subtract')],
 'Subtracting a number is adding its additive inverse: a − b = a + (−b). A negative subtraction therefore becomes a move right.',p=>result(`${p.a} − (${p.b}) = ${p.a-p.b}`,p.a-p.b,`What is ${p.a} − (${p.b})?`,[`Rewrite as ${p.a} + (${-p.b}).`,`Start at ${p.a} and move ${Math.abs(p.b)} units ${p.b>0?'left':'right'}.`,`You reach ${p.a-p.b}.`],lineDiagram(p.a,-p.b,p.a-p.b),'Subtracting reverses the direction associated with the subtracted number.'));
define('absolute-value','Absolute value & distance','foundations','Interpret absolute value as distance from zero.','Signed numbers',[A(-12,12,-6,'Number')],
 'Distance is nonnegative. The absolute value of a number tells how far it is from zero, without keeping its direction.',p=>result(`|${p.a}| = ${Math.abs(p.a)}`,Math.abs(p.a),`What is |${p.a}|?`,['Locate zero and the number on the line.',`Count the ${Math.abs(p.a)} unit intervals between them.`,`Distance has no negative direction, so |${p.a}| = ${Math.abs(p.a)}.`],lineDiagram(0,p.a,p.a,'distance'),'The highlighted segment measures distance, not a signed change.'));
define('factors-multiples','Factors & greatest common factor','foundations','Find the greatest factor shared by two positive integers.','Whole-number division',[A(1,24,12,'First integer'),B(1,24,18,'Second integer')],
 'A factor divides a number with no remainder. The greatest common factor is the largest member of both factor lists.',p=>{const factors=n=>range(n,i=>i+1).filter(x=>n%x===0),fa=factors(p.a),fb=factors(p.b);return result(`gcf(${p.a}, ${p.b}) = ${gcd(p.a,p.b)}`,gcd(p.a,p.b),`What is the greatest common factor of ${p.a} and ${p.b}?`,[`Factors of ${p.a}: ${fa.join(', ')}.`,`Factors of ${p.b}: ${fb.join(', ')}.`,`The largest shared factor is ${gcd(p.a,p.b)}.`],{type:'factors',fa,fb,a:p.a,b:p.b},'Shared factors are outlined in green; the largest is the greatest common factor.');});
define('fraction-equivalence','Equivalent fractions','foundations','Split each part equally without changing the amount.','Numerator and denominator',[A(1,5,2,'Shaded parts'),B(2,6,3,'Extra unshaded parts'),C(2,4,2,'Split each part into')],
 'Multiplying numerator and denominator by the same nonzero number partitions the same whole more finely. It does not change the fraction.',p=>{const d=p.a+p.b;return result(`${p.a}/${d} = ${p.a*p.c}/${d*p.c}`,p.a*p.c,`After multiplying both parts of ${p.a}/${d} by ${p.c}, what is the new numerator?`,[`Start with ${p.a} shaded parts out of ${d}.`,`Split every part into ${p.c} smaller equal parts.`,`There are ${p.a*p.c} shaded parts out of ${d*p.c}; the shaded length is unchanged.`],{type:'fractions',rows:[{n:p.a,d,label:`${p.a}/${d}`},{n:p.a*p.c,d:d*p.c,label:`${p.a*p.c}/${d*p.c}`} ]},'Both bars represent the same-sized whole.');});
define('fraction-addition','Add fractions','foundations','Use a common denominator to combine equal-sized parts.','Equivalent fractions',[A(1,5,1,'First numerator'),B(2,6,3,'First denominator'),C(2,6,4,'Second denominator')],
 'Fractions can be added directly only when their parts have equal size. A common denominator creates matching units.',p=>{const den=p.b*p.c/gcd(p.b,p.c),n=p.a*den/p.b+den/p.c;return result(`${p.a}/${p.b} + 1/${p.c} = ${frac(n,den)}`,n/den,`What is ${p.a}/${p.b} + 1/${p.c}?`,[`Use common denominator ${den}.`,`${p.a}/${p.b} = ${p.a*den/p.b}/${den}, and 1/${p.c} = ${den/p.c}/${den}.`,`Add the numerators: ${n}/${den} = ${frac(n,den)}.`],{type:'fractions',rows:[{n:p.a,d:p.b,label:`${p.a}/${p.b}`},{n:1,d:p.c,label:`1/${p.c}`},{n,d:den,label:'sum'}]},'Each bar uses equal-sized wholes; values above 1 extend across multiple whole bars.');});
define('fraction-multiplication','Multiply fractions','foundations','See a fraction of a fraction as overlapping area.','Fractions as equal parts',[A(1,4,2,'Selected columns'),B(1,4,1,'Selected rows')],
 'Taking a fraction of a fraction keeps only the overlap. The numerator counts overlapping cells; the denominator counts all cells in the whole.',p=>result(`${p.a}/5 × ${p.b}/5 = ${p.a*p.b}/25`,p.a*p.b/25,`What is ${p.a}/5 × ${p.b}/5?`,['Divide the square into 5 columns and 5 rows.',`Select ${p.a} columns and ${p.b} rows. Their overlap contains ${p.a*p.b} cells.`,`There are 25 equal cells, so the product is ${p.a*p.b}/25 = ${fmt(p.a*p.b/25)}.`],{type:'fractionGrid',cols:5,rows:5,a:p.a,b:p.b},'Dark cells belong to both selected strips.'));
define('fraction-division','Divide fractions','foundations','Count how many fractional groups fit in an amount.','Fraction multiplication',[A(1,6,3,'Amount numerator'),B(2,6,4,'Denominator')],
 'Dividing by 1/d asks how many pieces of size 1/d fit. An amount of a/d contains exactly a of those pieces.',p=>result(`${p.a}/${p.b} ÷ 1/${p.b} = ${p.a}`,p.a,`How many pieces of size 1/${p.b} fit in ${p.a}/${p.b}?`,[`The amount is ${p.a} pieces, each of size 1/${p.b}.`,`One group uses exactly one such piece.`,`Therefore ${p.a}/${p.b} ÷ 1/${p.b} = ${p.a}.`],{type:'fractions',rows:[{n:p.a,d:p.b,label:'amount'},{n:1,d:p.b,label:'one group'}]},'This introduction uses a unit-fraction divisor; both bars share the same whole.'));
define('decimals-percents','Decimals, fractions & percents','foundations','Connect hundredths to decimal and percent notation.','Fractions with denominator 100',[A(0,100,35,'Shaded hundredths')],
 'Percent means per hundred. A decimal such as 0.35, a fraction such as 35/100, and 35% can describe the same portion.',p=>result(`${p.a}/100 = ${fmt(p.a/100)} = ${p.a}%`,p.a/100,`Write ${p.a}% as a decimal.`,['Interpret the percent as a number of hundredths.',`${p.a}% = ${p.a}/100.`,`Divide by 100: ${fmt(p.a/100)}.`],{type:'fractionGrid',cols:10,rows:10,count:p.a},'Each cell is one hundredth of the same whole.'));
define('powers','Powers & repeated multiplication','foundations','Understand an exponent as a count of equal factors.','Whole-number multiplication',[A(1,5,2,'Base'),B(0,5,3,'Exponent')],
 'For a positive integer exponent, a power multiplies the base by itself that many times. A nonzero base to the zero power equals 1.',p=>result(`${p.a}^${p.b} = ${p.a**p.b}`,p.a**p.b,`Evaluate ${p.a}^${p.b}.`,[p.b===0?'Use the zero-exponent rule for a nonzero base.':`Write ${p.b} equal factors of ${p.a}.`,p.b===0?'A product with no factors has multiplicative identity 1.':range(p.b,()=>p.a).join(' × ')+'.',`The result is ${p.a**p.b}.`],{type:'growth',values:range(p.b+1,i=>p.a**i),labels:range(p.b+1,i=>`n=${i}`)},'The bars show successive powers, beginning with exponent zero.'));
define('order-operations','Order of operations','foundations','Distinguish grouping from multiplication and addition.','Addition and multiplication',[A(1,9,2,'a'),B(1,9,3,'b'),C(1,9,4,'c')],
 'Grouping symbols decide which quantities form a unit. Without parentheses, multiplication is evaluated before addition.',p=>result(`${p.a} + ${p.b} × ${p.c} = ${p.a+p.b*p.c}`,p.a+p.b*p.c,`Evaluate ${p.a} + ${p.b} × ${p.c}.`,[`Identify the product ${p.b} × ${p.c}.`,`Multiply first: ${p.b} × ${p.c} = ${p.b*p.c}.`,`Then add ${p.a}: ${p.a+p.b*p.c}. Parentheses (${p.a}+${p.b})×${p.c} would give ${(p.a+p.b)*p.c}.`],{type:'bars',values:[p.a,p.b*p.c,(p.a+p.b)*p.c],labels:['a','b × c','(a+b) × c']},'The grouped expression is included for comparison, not as a second answer.'));

define('unit-rates','Unit rates','ratios','Scale a ratio down to one unit.','Division',[A(2,12,6,'Cost in dollars'),B(1,6,3,'Number of items')],
 'A unit rate compares a quantity with one unit of another quantity. Dividing both quantities by the item count preserves the ratio.',p=>result(`$${p.a} ÷ ${p.b} = $${fmt(p.a/p.b)} per item`,p.a/p.b,`What is the cost per item if ${p.b} items cost $${p.a}?`,[`Start with $${p.a} for ${p.b} items.`,`Divide dollars and item count by ${p.b}.`,`One item costs $${fmt(p.a/p.b)}.`],graphDiagram([x=>p.a/p.b*x],[0,6],[0,Math.max(6,p.a/p.b*6)],[[p.b,p.a]]),'Horizontal axis: items. Vertical axis: dollars. The proportional model assumes the same price for every item.'));
define('proportions','Proportional relationships','ratios','Connect a constant ratio to a line through the origin.','Multiplication and unit rates',[A(1,6,3,'Rate k'),B(0,8,4,'Input x')],
 'In y = kx, the ratio y/x is k whenever x is nonzero. At x = 0, the output is 0, so the graph passes through the origin.',p=>result(`y = ${p.a}x; y(${p.b}) = ${p.a*p.b}`,p.a*p.b,`If y = ${p.a}x, what is y when x = ${p.b}?`,[`The constant of proportionality is ${p.a}.`,`Multiply the input ${p.b} by ${p.a}.`,`The output is ${p.a*p.b}.`],graphDiagram([x=>p.a*x],[0,8],[0,Math.max(8,p.a*8)],[[p.b,p.a*p.b]]),'Changing k changes the rate; the line continues to pass through (0, 0).'));
define('percent-of','Find a percent of a quantity','ratios','Use a percent as a multiplicative scale factor.','Decimal multiplication',[A(10,200,80,'Original quantity'),inp('b','Percent',0,100,25,5)],
 'To find p percent of an amount, multiply by p/100. The shaded bar shows the selected portion of the whole.',p=>result(`${p.b}% of ${p.a} = ${fmt(p.a*p.b/100)}`,p.a*p.b/100,`What is ${p.b}% of ${p.a}?`,[`Convert ${p.b}% to ${fmt(p.b/100)}.`,`Multiply ${p.a} × ${fmt(p.b/100)}.`,`The selected quantity is ${fmt(p.a*p.b/100)}.`],{type:'portion',part:p.a*p.b/100,total:p.a,labels:['selected','remaining']},'The full bar represents the original quantity.'));
define('percent-change','Percent increase & decrease','ratios','Measure a change relative to the original amount.','Percent of a quantity',[A(20,200,100,'Original amount'),inp('b','Percent change',-80,100,20,5)],
 'A percent change uses the original amount as the reference. Multiply the original by 1 + p/100, including a negative p for a decrease.',p=>result(`${p.a} × ${fmt(1+p.b/100)} = ${fmt(p.a*(1+p.b/100))}`,p.a*(1+p.b/100),`Start at ${p.a} and change by ${p.b}%. What is the new amount?`,[`The signed change is ${p.a} × ${p.b}/100 = ${fmt(p.a*p.b/100)}.`,`Add it to the original amount.`,`The result is ${fmt(p.a*(1+p.b/100))}.`],{type:'bars',values:[p.a,p.a*(1+p.b/100)],labels:['original','new amount']},'Both bars use one scale, so their lengths can be compared.'));
define('scale-drawings','Scale drawings','ratios','Use a scale factor to map a drawing to a real length.','Ratios and multiplication',[A(1,10,4,'Drawing length (cm)'),B(2,20,5,'Real meters per drawing cm')],
 'A scale specifies how much real distance one drawing unit represents. Multiplying by the scale converts drawing length to real length.',p=>result(`${p.a} cm × ${p.b} m/cm = ${p.a*p.b} m`,p.a*p.b,`At ${p.b} meters per drawing centimeter, how many real meters does ${p.a} cm represent?`,[`One drawing centimeter represents ${p.b} real meters.`,`There are ${p.a} drawing centimeters.`,`Multiply: ${p.a} × ${p.b} = ${p.a*p.b} meters.`],{type:'doubleline',top:p.a,bottom:p.a*p.b,topLabel:'drawing cm',bottomLabel:'real meters'},'The aligned ticks are corresponding quantities, not equal physical lengths.'));
define('simple-interest','Simple interest','ratios','Separate principal from interest earned at a constant rate.','Percents and multiplication',[inp('a','Principal ($)',100,1000,500,100),B(1,10,5,'Annual rate (%)'),C(1,10,3,'Years')],
 'Simple interest is calculated from the original principal each period. The interest is I = Prt, with r written as a decimal.',p=>result(`I = $${fmt(p.a*p.b/100*p.c)}`,p.a*p.b/100*p.c,`How much simple interest does $${p.a} earn at ${p.b}% for ${p.c} years?`,[`Convert the annual rate to ${fmt(p.b/100)}.`,`Multiply principal × rate × years.`,`I = ${p.a} × ${fmt(p.b/100)} × ${p.c} = $${fmt(p.a*p.b/100*p.c)}. The final balance adds the principal.`],graphDiagram([x=>p.a*p.b/100*x],[0,10],[0,p.a*.1*10],[[p.c,p.a*p.b/100*p.c]]),'Horizontal axis: years. Vertical axis: interest in dollars. No compounding, fees, or changing rates.'));

define('distributive-property','The distributive property','prealgebra','Break a product into two matching partial products.','Area of rectangles',[A(1,8,3,'Height a'),B(1,8,4,'Width b'),C(1,8,2,'Width c')],
 'A rectangle with width b + c can be split into widths b and c without changing its total area. Thus a(b + c) = ab + ac.',p=>result(`${p.a}(${p.b} + ${p.c}) = ${p.a*p.b} + ${p.a*p.c} = ${p.a*(p.b+p.c)}`,p.a*(p.b+p.c),`Evaluate ${p.a}(${p.b} + ${p.c}).`,[`Split the width into ${p.b} and ${p.c}.`,`The partial areas are ${p.a} × ${p.b} = ${p.a*p.b} and ${p.a} × ${p.c} = ${p.a*p.c}.`,`Add the parts: ${p.a*(p.b+p.c)} square units.`],{type:'areaSplit',a:p.a,b:p.b,c:p.c},'The two rectangles share a height and exactly fill the original rectangle.'));
define('combine-like-terms','Combine like terms','prealgebra','Group equal kinds of quantities by their coefficients.','Variables and multiplication',[A(-5,8,3,'Coefficient a'),B(-5,8,2,'Coefficient b'),C(1,6,4,'Value of x')],
 'Like terms have the same variable part. Adding ax and bx changes the count of x-sized groups, giving (a + b)x.',p=>result(`${p.a}x + (${p.b})x = ${p.a+p.b}x`,(p.a+p.b)*p.c,`At x = ${p.c}, what is ${p.a}x + (${p.b})x?`,[`Both terms have the same variable part x.`,`Add coefficients: ${p.a} + (${p.b}) = ${p.a+p.b}.`,`At x = ${p.c}, multiply ${p.a+p.b} × ${p.c} = ${(p.a+p.b)*p.c}.`],{type:'bars',values:[p.a*p.c,p.b*p.c,(p.a+p.b)*p.c],labels:['ax','bx','sum']},'Signed bars extend on opposite sides of zero. Negative coefficients represent subtraction.'));
define('linear-equations','Solve two-step equations','prealgebra','Undo operations equally on both sides to isolate x.','Inverse operations and signed numbers',[A(1,6,2,'Coefficient a'),B(-6,6,3,'Constant b'),C(-20,30,11,'Right-hand side c')],
 'Applying the same reversible operation to both sides preserves the solution. Undo addition first and multiplication second.',p=>{const x=(p.c-p.b)/p.a;return result(`${p.a}x + (${p.b}) = ${p.c}; x = ${fmt(x)}`,x,`Solve ${p.a}x + (${p.b}) = ${p.c}.`,[`Subtract ${p.b} from both sides: ${p.a}x = ${p.c-p.b}.`,`Divide both sides by the nonzero coefficient ${p.a}: x = ${frac(p.c-p.b,p.a)}.`,`Check: ${p.a} × (${fmt(x)}) + (${p.b}) = ${p.c}${Number.isInteger(x)?'.':' (using the exact fractional value).'}`],{type:'equationBalance',a:p.a,b:p.b,c:p.c,x},'The three signed bars show the variable term, constant term, and right-hand side. The first two add to the third; they do not each equal it.');});
define('inequalities','Inequalities & sign reversal','prealgebra','See why dividing by a negative number reverses an inequality.','Solving linear equations',[A(-5,-1,-2,'Negative coefficient a'),B(-5,5,3,'Boundary k')],
 'Multiplication by a negative reverses order on the number line. Therefore dividing both sides of an inequality by a negative also reverses its comparison sign.',p=>result(`${p.a}x < ${p.a*p.b}  ⇔  x > ${p.b}`,p.b,`For ${p.a}x < ${p.a*p.b}, what boundary value appears in x > ___?`,[`Divide both sides by ${p.a}.`,`Because ${p.a} is negative, reverse < to >.`,`The solution set is x > ${p.b}. The boundary is excluded.`],{type:'inequality',boundary:p.b,direction:1,open:true},'An open circle excludes the boundary. The ray extends right for greater-than values.','This lesson models a strict inequality with a negative coefficient.'));
define('coordinate-plane','The coordinate plane','prealgebra','Read ordered pairs as horizontal and vertical moves.','Signed numbers and number lines',[A(-6,6,3,'x-coordinate'),B(-6,6,-2,'y-coordinate')],
 'An ordered pair (x, y) gives two coordinates. Move horizontally from the origin using x, then vertically using y.',p=>result(`P = (${p.a}, ${p.b})`,p.a,`What is the x-coordinate of P = (${p.a}, ${p.b})?`,['Start at the origin (0, 0).',`Move ${Math.abs(p.a)} units ${p.a<0?'left':'right'}, then ${Math.abs(p.b)} units ${p.b<0?'down':'up'}.`,`The first coordinate is x = ${p.a}; the second is y = ${p.b}.`],graphDiagram([],[-7,7],[-7,7],[[p.a,p.b]]),'The dashed guides locate the point relative to both axes.'));
define('scientific-notation','Scientific notation','prealgebra','Connect powers of ten with changing magnitude.','Powers and decimal place value',[inp('a','Leading factor',1,9,3,.5),B(-5,5,4,'Power of ten')],
 'Scientific notation writes a number as a × 10ⁿ with 1 ≤ |a| < 10. A positive power makes it larger; a negative power makes it smaller.',p=>result(`${fmt(p.a)} × 10^${p.b} = ${fmt(p.a*10**p.b)}`,p.a*10**p.b,`Evaluate ${fmt(p.a)} × 10^${p.b}.`,[`The leading factor is ${fmt(p.a)}.`,`10^${p.b} = ${Number(10**p.b).toLocaleString('en-US',{maximumFractionDigits:8})}.`,`Multiplying gives ${Number(p.a*10**p.b).toLocaleString('en-US',{maximumFractionDigits:8})}.`],{type:'powerscale',a:p.a,n:p.b},'The exponent axis is logarithmic: moving one step right multiplies the value by ten.','Use ordinary decimal notation or e notation in the practice answer.'));

define('slope','Slope: rise over run','algebra1','Connect changes in coordinates to the slope of a line.','Coordinates and division',[A(-5,5,3,'Rise'),B(1,5,2,'Run')],
 'Slope compares vertical change with horizontal change: m = Δy/Δx. A negative rise gives a downward-sloping line.',p=>result(`m = ${p.a}/${p.b} = ${fmt(p.a/p.b)}`,p.a/p.b,`What is the slope for a rise of ${p.a} and a run of ${p.b}?`,[`Start with (0, 0) and (${p.b}, ${p.a}).`,`The vertical change is ${p.a}; the horizontal change is ${p.b}.`,`Divide rise by run: m = ${frac(p.a,p.b)}.`],graphDiagram([x=>p.a/p.b*x],[-6,6],[-8,8],[[0,0],[p.b,p.a]]),'The graph shows a fixed window; some of a steep line may lie outside it.'));
define('slope-intercept','Slope-intercept form','algebra1','Change slope and intercept and watch their different effects.','Slope and coordinate graphing',[inp('a','Slope m',-3,3,1,.5),B(-5,5,2,'Intercept b'),C(-4,4,3,'Input x')],
 'In y = mx + b, b is the output at x = 0. The slope m is the change in y for each unit increase in x.',p=>result(`y = ${fmt(p.a)}x + (${p.b}); y(${p.c}) = ${fmt(p.a*p.c+p.b)}`,p.a*p.c+p.b,`For y = ${fmt(p.a)}x + (${p.b}), find y at x = ${p.c}.`,[`Multiply m × x = ${fmt(p.a*p.c)}.`,`Add the intercept ${p.b}.`,`The output is ${fmt(p.a*p.c+p.b)}.`],graphDiagram([x=>p.a*x+p.b],[-6,6],[-12,12],[[0,p.b],[p.c,p.a*p.c+p.b]]),'The intercept moves the line vertically; slope changes its direction and steepness.'));
define('systems','Systems of linear equations','algebra1','Find the input-output pair that lies on two lines.','Linear equations and graphing',[A(-3,3,1,'First slope m'),B(-4,4,2,'First intercept b'),C(-4,4,-2,'Second intercept c')],
 'A solution of a system must satisfy both equations at once. Distinct nonparallel lines meet at one point.',p=>{const x=(p.c-p.b)/(2*p.a+1),y=p.a*x+p.b;return result(`(${fmt(x)}, ${fmt(y)})`,x,`Find the x-coordinate where y = ${p.a}x + (${p.b}) and y = ${-p.a-1}x + (${p.c}) meet.`,['Set the two expressions for y equal.',`${2*p.a+1}x = ${p.c-p.b}.`,`x = ${fmt(x)}, and substituting gives y = ${fmt(y)}.`],graphDiagram([t=>p.a*t+p.b,t=>(-p.a-1)*t+p.c],[-9,9],[-15,15],[[x,y]]),'The highlighted point satisfies both equations. Controls keep these two lines nonparallel.','Parallel lines can have no solution; identical lines have infinitely many. Those cases require separate reasoning.');});
define('function-input-output','Function notation','algebra1','Treat f(x) as a rule applied to a chosen input.','Substitution and powers',[A(-3,3,2,'Constant k'),B(-4,4,3,'Input x')],
 'A function assigns exactly one output to each allowed input. In f(x) = x² + k, square the input and then add k.',p=>result(`f(${p.b}) = ${p.b}² + (${p.a}) = ${p.b*p.b+p.a}`,p.b*p.b+p.a,`If f(x) = x² + (${p.a}), find f(${p.b}).`,[`Substitute ${p.b} for every x.`,`Square the input: (${p.b})² = ${p.b*p.b}.`,`Add ${p.a}: f(${p.b}) = ${p.b*p.b+p.a}.`],graphDiagram([x=>x*x+p.a],[-5,5],[-5,25],[[p.b,p.b*p.b+p.a]]),'The marked input has one output. The notation f(x) is not multiplication by f.'));
define('quadratic-vertex','Quadratics & the vertex','algebra1','Use vertex form to locate a parabola’s turning point.','Coordinates and squaring',[A(-3,3,1,'Horizontal shift h'),B(-3,5,2,'Vertical shift k'),inp('c','Scale a',.5,2,1,.5)],
 'In y = a(x − h)² + k with a > 0, the squared part is smallest at x = h. The minimum is therefore the vertex (h, k).',p=>result(`y = ${fmt(p.c)}(x − (${p.a}))² + (${p.b})`,p.b,`What is the minimum y-value of this parabola?`,['A real square is always at least zero.',`At x = ${p.a}, the squared part is zero.`,`The minimum output is k = ${p.b}.`],graphDiagram([x=>p.c*(x-p.a)**2+p.b],[-6,6],[-5,20],[[p.a,p.b]]),'Changing h moves the vertex horizontally; k moves it vertically; a changes width.'));
define('factor-quadratics','Factoring & zeros','algebra1','Connect factored form to where a parabola crosses the axis.','Multiplication and the zero-product property',[A(-4,4,-2,'First root r'),B(-4,4,3,'Second root s')],
 'A product is zero when at least one factor is zero. In (x − r)(x − s), the roots are r and s.',p=>result(`(x − (${p.a}))(x − (${p.b})) = 0`,p.a+p.b,`What is the sum of the two roots, counting a repeated root twice?`,[`Set x − (${p.a}) = 0 to get x = ${p.a}.`,`Set x − (${p.b}) = 0 to get x = ${p.b}.`,`Add the roots: ${p.a} + (${p.b}) = ${p.a+p.b}.`],graphDiagram([x=>(x-p.a)*(x-p.b)],[-6,6],[-15,20],[[p.a,0],[p.b,0]]),'When roots coincide, the parabola touches the axis at a repeated root.'));
define('absolute-value-graphs','Absolute-value graphs','algebra1','Interpret a V-shaped graph as distance from a shifted point.','Absolute value and coordinates',[A(-4,4,1,'Horizontal shift h'),B(-3,4,0,'Vertical shift k'),C(-5,5,3,'Input x')],
 'The quantity |x − h| measures horizontal distance from h. Adding k shifts every output vertically.',p=>result(`f(${p.c}) = |${p.c} − (${p.a})| + (${p.b}) = ${Math.abs(p.c-p.a)+p.b}`,Math.abs(p.c-p.a)+p.b,`For f(x) = |x − (${p.a})| + (${p.b}), find f(${p.c}).`,[`Compute the signed difference: ${p.c-p.a}.`,`Take its distance from zero: ${Math.abs(p.c-p.a)}.`,`Add ${p.b} to get ${Math.abs(p.c-p.a)+p.b}.`],graphDiagram([x=>Math.abs(x-p.a)+p.b],[-6,6],[-4,12],[[p.a,p.b],[p.c,Math.abs(p.c-p.a)+p.b]]),'The vertex is the shifted point (h, k).'));

define('rectangle-area','Area & perimeter','geometry','Distinguish covering a region from measuring its boundary.','Multiplication and length units',[A(1,12,6,'Width'),B(1,9,4,'Height')],
 'Area counts square units that cover a region. Perimeter counts length units around its outside. They measure different things.',p=>result(`A = ${p.a*p.b} units²; P = ${2*(p.a+p.b)} units`,p.a*p.b,`What is the area of a ${p.a}-by-${p.b} rectangle?`,[`Each row contains ${p.a} unit squares.`,`There are ${p.b} rows.`,`Multiply: A = ${p.a} × ${p.b} = ${p.a*p.b} square units.`],shapeDiagram('rectangle',{a:p.a,b:p.b}),'The interior grid shows area. The outer border measures perimeter.'));
define('triangle-area','Why triangle area is half','geometry','Pair two triangles to make a rectangle.','Rectangle area',[A(1,12,8,'Base'),B(1,9,5,'Perpendicular height')],
 'Two congruent right triangles fit into a rectangle with the same base and height. One triangle has half that area. Any triangle has the same formula with its perpendicular height.',p=>result(`A = ½ × ${p.a} × ${p.b} = ${fmt(p.a*p.b/2)}`,p.a*p.b/2,`Find the area of a triangle with base ${p.a} and perpendicular height ${p.b}.`,[`A matching rectangle has area ${p.a} × ${p.b} = ${p.a*p.b}.`,`The diagonal splits that rectangle into two congruent triangles.`,`One triangle has area ${fmt(p.a*p.b/2)} square units.`],shapeDiagram('triangle',{a:p.a,b:p.b}),'The pale triangle completes the rectangle. The height is perpendicular to the base.'));
define('trapezoid-area','Area of a trapezoid','geometry','Average the parallel bases before multiplying by height.','Triangle and rectangle areas',[A(2,10,7,'Bottom base'),B(1,8,3,'Top base'),C(1,8,4,'Height')],
 'A trapezoid’s area equals its height times the average of its two parallel bases. Two copies can form a parallelogram of base b₁ + b₂.',p=>result(`A = ½(${p.a} + ${p.b}) × ${p.c} = ${fmt((p.a+p.b)*p.c/2)}`,(p.a+p.b)*p.c/2,`Find the trapezoid area for bases ${p.a}, ${p.b}, and height ${p.c}.`,[`Add the parallel base lengths: ${p.a+p.b}.`,`Multiply by height: ${(p.a+p.b)*p.c}.`,`Take half: ${fmt((p.a+p.b)*p.c/2)} square units.`],shapeDiagram('trapezoid',{a:p.a,b:p.b,c:p.c}),'Only the two parallel sides are averaged. The height is a perpendicular distance.'));
define('circle-measurement','Circles: radius, circumference, area','geometry','Compare linear and square measures as the radius changes.','Multiplication and π',[A(1,10,4,'Radius')],
 'The circumference is 2πr, a length. The area is πr², a count of square units. Doubling the radius doubles circumference and quadruples area.',p=>result(`C = ${fmt(2*Math.PI*p.a)}; A = ${fmt(Math.PI*p.a*p.a)}`,Math.PI*p.a*p.a,`What is the area of a circle with radius ${p.a}?`,[`Use A = πr².`,`Square the radius: ${p.a}² = ${p.a*p.a}.`,`Multiply by π: ${p.a*p.a}π ≈ ${fmt(Math.PI*p.a*p.a)} square units.`],shapeDiagram('circle',{a:p.a}),'The radius runs from the center to the circumference. Units are arbitrary length units.'));
define('pythagorean','The Pythagorean theorem','geometry','Connect the areas of squares built on a right triangle.','Squares, square roots and right angles',[A(1,8,3,'Leg a'),B(1,8,4,'Leg b')],
 'For a right triangle, the square on the hypotenuse has the same area as the two squares on its legs combined: a² + b² = c².',p=>{const h=Math.hypot(p.a,p.b);return result(`${p.a}² + ${p.b}² = c²; c = ${fmt(h)}`,h,`Find the hypotenuse for perpendicular legs ${p.a} and ${p.b}.`,[`Square the legs: ${p.a*p.a} and ${p.b*p.b}.`,`Add: c² = ${p.a*p.a+p.b*p.b}.`,`Take the nonnegative square root: c = ${fmt(h)}.`],shapeDiagram('pythagorean',{a:p.a,b:p.b,c:h}),'The small bars below the triangle compare a², b², and c² on a shared area scale.','This theorem applies to right triangles. The diagram illustrates the relationship; a full proof needs a dissection or equivalent argument.');});
define('triangle-angles','Angles in a triangle','geometry','Find a missing angle using the straight-angle sum.','Angles measured in degrees',[A(20,80,50,'First angle'),B(20,80,60,'Second angle')],
 'In Euclidean geometry, the three interior angles of a triangle sum to 180°. A line through a vertex parallel to the opposite side relates the other two angles by alternate interior angles.',p=>result(`${p.a}° + ${p.b}° + C = 180°; C = ${180-p.a-p.b}°`,180-p.a-p.b,`What is the third angle when the other two are ${p.a}° and ${p.b}°?`,[`The angle sum is 180°.`,`Add the known angles: ${p.a+p.b}°.`,`Subtract: C = 180 − ${p.a+p.b} = ${180-p.a-p.b}°.`],shapeDiagram('angleTriangle',{a:p.a,b:p.b,c:180-p.a-p.b}),'The triangle’s geometry is constructed from the chosen angles.'));
define('supplementary-angles','Adjacent & supplementary angles','geometry','Use a straight angle to find its missing part.','Degree measure',[A(10,170,65,'First angle')],
 'A straight angle measures 180°. Adjacent angles that form a straight line therefore add to 180°.',p=>result(`${p.a}° + ${180-p.a}° = 180°`,180-p.a,`Find the angle supplementary to ${p.a}°.`,['Identify the straight line, which measures 180°. ',`One part measures ${p.a}°.`,`The remaining part is 180 − ${p.a} = ${180-p.a}°.`],shapeDiagram('angles',{a:p.a}),'The ray splits one straight angle into two adjacent parts.'));
define('polygon-angles','Interior angles of regular polygons','geometry','Decompose a polygon into triangles to find its angle sum.','Triangle angle sum',[A(3,10,5,'Number of sides n')],
 'A convex n-sided polygon can be divided from one vertex into n − 2 triangles. Its interior angle sum is (n − 2)180°. In a regular polygon all angles are equal.',p=>result(`Each angle = (${p.a} − 2)180° / ${p.a} = ${fmt((p.a-2)*180/p.a)}°`,(p.a-2)*180/p.a,`What is each interior angle of a regular ${p.a}-sided polygon?`,[`There are n − 2 = ${p.a-2} triangles.`,`Their angle sum is ${(p.a-2)*180}°.`,`Divide by ${p.a} equal angles to get ${fmt((p.a-2)*180/p.a)}°.`],shapeDiagram('polygon',{n:p.a}),'The diagonals from one vertex partition the convex polygon.'));
define('similarity-scale','Similarity & scale factors','geometry','Compare how length and area change under dilation.','Ratios and square area',[A(1,5,2,'Original side'),inp('b','Scale factor',.5,3,1.5,.5)],
 'A dilation multiplies every length by k. Since area is a product of two lengths, corresponding areas are multiplied by k².',p=>result(`New side = ${fmt(p.a*p.b)}; area factor = ${fmt(p.b*p.b)}`,p.b*p.b,`If a figure is enlarged by a length scale factor of ${fmt(p.b)}, what is the area scale factor?`,[`Each corresponding length is multiplied by ${fmt(p.b)}.`,`Area combines two lengths.`,`The area factor is ${fmt(p.b)}² = ${fmt(p.b*p.b)}.`],shapeDiagram('similarSquares',{a:p.a,b:p.b}),'Both squares use the same drawing scale. A scale below 1 gives a reduction.'));
define('translations','Coordinate translations','geometry','Move every point by the same vector.','Ordered pairs',[A(-3,3,2,'Horizontal move'),B(-3,3,1,'Vertical move')],
 'A translation adds the same horizontal and vertical displacement to every point. It preserves distances and angles.',p=>result(`(x, y) → (x + (${p.a}), y + (${p.b}))`,1+p.a,`Translate point (1, 2) by (${p.a}, ${p.b}). What is its new x-coordinate?`,[`Add ${p.a} to each x-coordinate.`,`Add ${p.b} to each y-coordinate.`,`Point (1, 2) becomes (${1+p.a}, ${2+p.b}).`],{type:'transform',kind:'translate',a:p.a,b:p.b},'The green triangle is the image of the gray original; vertex A begins at (1, 2).'));
define('reflections','Reflections across an axis','geometry','Compare a point with its mirror image across the y-axis.','Coordinates and opposites',[A(-4,4,3,'Point x'),B(-4,4,2,'Point y')],
 'Reflection across the y-axis reverses horizontal direction but preserves vertical position. Each point and its image are equally far from the mirror line.',p=>result(`(${p.a}, ${p.b}) → (${-p.a}, ${p.b})`,-p.a,`Reflect (${p.a}, ${p.b}) across the y-axis. What is its new x-coordinate?`,['Keep the same y-coordinate.',`Replace x = ${p.a} with its opposite ${-p.a}.`,`The reflected point is (${-p.a}, ${p.b}).`],graphDiagram([],[-6,6],[-6,6],[[p.a,p.b],[-p.a,p.b]]),'The y-axis is the mirror. Reflection preserves distance but reverses orientation.'));
define('rotations','Rotations about the origin','geometry','Rotate a triangle counterclockwise without changing its size.','Coordinates and right angles',[inp('a','Quarter turns counterclockwise',0,4,1,1)],
 'A 90° counterclockwise rotation maps (x, y) to (−y, x). Repeating this rule rotates by successive quarter turns.',p=>{let x=1,y=2;for(let i=0;i<p.a;i++)[x,y]=[-y,x];return result(`${p.a*90}°: A(1, 2) → (${x}, ${y})`,x,`Rotate (1, 2) counterclockwise by ${p.a*90}°. What is the new x-coordinate?`,[`Use (x, y) → (−y, x) for each quarter turn.`,`Apply it ${p.a} time${p.a===1?'':'s'}.`,`The image is (${x}, ${y}); distances from the origin are unchanged.`],{type:'transform',kind:'rotate',a:p.a,b:0},'The original and rotated triangles are congruent. A full turn returns to the starting position.');});
define('rectangular-prism','Volume of a rectangular prism','geometry','Count layers of equal-area bases.','Rectangle area',[A(1,8,4,'Length'),B(1,8,3,'Width'),C(1,8,5,'Height')],
 'A prism’s volume is base area times height. Each unit-height layer contains the same number of unit cubes.',p=>result(`V = ${p.a} × ${p.b} × ${p.c} = ${p.a*p.b*p.c}`,p.a*p.b*p.c,`Find the volume of a ${p.a} × ${p.b} × ${p.c} rectangular prism.`,[`The base area is ${p.a*p.b} square units.`,`There are ${p.c} unit-height layers.`,`Multiply to get ${p.a*p.b*p.c} cubic units.`],shapeDiagram('prism',{a:p.a,b:p.b,c:p.c}),'The solid uses a consistent isometric projection; the highlighted top layer has the same area as the base.'));
define('surface-area','Surface area of a box','geometry','Add the areas of the six faces of a rectangular prism.','Rectangle area and nets',[A(1,6,4,'Length'),B(1,6,3,'Width'),C(1,6,2,'Height')],
 'The three different face areas each occur twice. Surface area is the sum of their areas, measured in square units.',p=>result(`SA = 2(${p.a*p.b} + ${p.a*p.c} + ${p.b*p.c}) = ${2*(p.a*p.b+p.a*p.c+p.b*p.c)}`,2*(p.a*p.b+p.a*p.c+p.b*p.c),`Find the surface area of a ${p.a} × ${p.b} × ${p.c} box.`,[`Two faces have area ${p.a*p.b}, two have area ${p.a*p.c}, and two have area ${p.b*p.c}.`,`Add one of each: ${p.a*p.b+p.a*p.c+p.b*p.c}.`,`Double that sum: ${2*(p.a*p.b+p.a*p.c+p.b*p.c)} square units.`],shapeDiagram('net',{a:p.a,b:p.b,c:p.c}),'The net unfolds all six faces without changing their areas.'));
for(const kind of ['cylinder','cone','sphere'])define(`volume-${kind}`,`Volume of a ${kind}`,'geometry',`Connect ${kind} dimensions to its volume formula.`,'Circle area, multiplication and powers',[A(1,6,3,'Radius'),...(kind==='sphere'?[]:[B(1,10,5,'Height')])],
 kind==='cylinder'?'A cylinder has the same circular cross-section at every height. Its volume is πr²h.':kind==='cone'?'A cone has one third the volume of a cylinder with the same base radius and height. This volume relationship is more than a surface-area comparison.':'A sphere has volume (4/3)πr³. The cubic power explains why doubling its radius multiplies volume by eight.',p=>{const v=kind==='sphere'?4/3*Math.PI*p.a**3:(kind==='cone'?1/3:1)*Math.PI*p.a*p.a*p.b;return result(`V = ${kind==='sphere'?'(4/3)πr³':kind==='cone'?'⅓πr²h':'πr²h'} ≈ ${fmt(v)}`,v,`Find the ${kind} volume for radius ${p.a}${kind==='sphere'?'':` and height ${p.b}`}.`,[`Use the ${kind} volume formula.`,kind==='sphere'?`r³ = ${p.a**3}.`:`The circular base has area ${p.a*p.a}π; multiply by height ${p.b}.`,`The volume is approximately ${fmt(v)} cubic units.`],shapeDiagram(kind,{a:p.a,b:p.b||p.a*2}),`Dimensions use one scale; hidden surfaces are not extra faces. Volume is in cubic units.`);});
define('arc-length','Arc length & central angles','geometry','Measure a fraction of a circle’s circumference.','Circle circumference and proportions',[A(1,8,4,'Radius'),inp('b','Central angle (degrees)',15,330,90,15)],
 'A central angle θ degrees selects θ/360 of the circumference. Arc length is that fraction of 2πr.',p=>result(`s = (${p.b}/360) × 2π × ${p.a} ≈ ${fmt(p.b/360*2*Math.PI*p.a)}`,p.b/360*2*Math.PI*p.a,`Find the arc length for radius ${p.a} and central angle ${p.b}°.`,[`The arc is ${p.b}/360 of a full circle.`,`The circumference is ${2*p.a}π.`,`Multiply to get arc length ${fmt(p.b/360*2*Math.PI*p.a)}.`],shapeDiagram('arc',{a:p.a,b:p.b}),'The highlighted arc follows the circle; the straight sides are radii.'));

define('exponent-laws','Multiply powers with the same base','algebra2','Count factors to explain why exponents add.','Powers and multiplication',[A(1,4,2,'First exponent m'),B(1,4,3,'Second exponent n')],
 'Multiplying 2ᵐ by 2ⁿ concatenates m factors of 2 with n more factors of 2. This gives m + n factors in total.',p=>result(`2^${p.a} × 2^${p.b} = 2^${p.a+p.b} = ${2**(p.a+p.b)}`,p.a+p.b,`Write 2^${p.a} × 2^${p.b} as a power of 2. What is the exponent?`,[`The first factor contributes ${p.a} copies of 2.`,`The second contributes ${p.b} copies of 2.`,`There are ${p.a+p.b} factors, so the exponent is ${p.a+p.b}.`],{type:'growth',values:range(p.a+p.b+1,i=>2**i),labels:range(p.a+p.b+1,i=>String(i))},'Each successive bar doubles. Exponents add here because the bases are the same.'));
define('radicals','Square roots & irrational numbers','algebra2','Find the nonnegative side length of a square with a known area.','Square area and real numbers',[A(1,50,18,'Square area')],
 'The principal square root √A is the nonnegative number whose square is A. If A is not a perfect square, its square root is irrational for positive integer A.',p=>result(`s = √${p.a} ≈ ${fmt(Math.sqrt(p.a))}`,Math.sqrt(p.a),`A square has area ${p.a}. What is its side length?`,['Use A = s² with s nonnegative.',`Take the principal square root of ${p.a}.`,`s ≈ ${fmt(Math.sqrt(p.a))}. ${Number.isInteger(Math.sqrt(p.a))?'This is a perfect square.':'This decimal is an approximation to an irrational number.'}`],shapeDiagram('rectangle',{a:Math.sqrt(p.a),b:Math.sqrt(p.a)}),'The square’s area is the input; its side is the square root.'));
define('quadratic-formula','The quadratic formula','algebra2','Relate the discriminant to the real roots of a quadratic.','Factoring, radicals and equations',[A(-4,4,-2,'Coefficient b'),B(-4,4,-3,'Coefficient c')],
 'For x² + bx + c = 0, completing the square leads to x = (−b ± √(b² − 4c))/2. The discriminant decides how many distinct real roots exist.',p=>{const d=p.a*p.a-4*p.b,root=d>=0?(-p.a+Math.sqrt(d))/2:0;return result(`D = ${d}; ${d<0?'no real roots':`x = ${fmt((-p.a-Math.sqrt(d))/2)}, ${fmt(root)}`}`,d,`What is the discriminant of x² + (${p.a})x + (${p.b}) = 0?`,[`For a = 1, use D = b² − 4c.`,`Compute (${p.a})² − 4(${p.b}) = ${d}.`,d>0?'Positive discriminant: two distinct real roots.':d===0?'Zero discriminant: one repeated real root.':'Negative discriminant: no real roots; the two roots are nonreal complex conjugates.'],graphDiagram([x=>x*x+p.a*x+p.b],[-7,7],[-10,20]),'The practice question asks for the discriminant, which can be negative.');});
define('polynomial-structure','Polynomial multiplication','algebra2','Use an area model to multiply two binomials.','Distribution and combining like terms',[A(1,6,2,'Constant a'),B(1,6,3,'Constant b'),C(1,5,2,'Value of x')],
 'Every part of one factor multiplies every part of the other. The four partial products combine into x² + (a + b)x + ab.',p=>result(`(x + ${p.a})(x + ${p.b}) = x² + ${p.a+p.b}x + ${p.a*p.b}`,(p.c+p.a)*(p.c+p.b),`At x = ${p.c}, what is (x + ${p.a})(x + ${p.b})?`,[`Expand: x² + ${p.b}x + ${p.a}x + ${p.a*p.b}.`,`Combine like terms: x² + ${p.a+p.b}x + ${p.a*p.b}.`,`At x = ${p.c}, the value is ${(p.c+p.a)*(p.c+p.b)}.`],{type:'binomialArea',x:p.c,a:p.a,b:p.b},'The four regions show all pairwise products. Positive dimensions are used for this area model.'));
define('rational-functions','Rational functions & domain','algebra2','See a denominator restriction and its vertical asymptote.','Fractions, division by zero and graphing',[A(-3,3,1,'Excluded input h'),B(1,4,2,'Numerator a')],
 'Division by zero is undefined. In f(x) = a/(x − h) with a nonzero, x = h is excluded and the graph has a vertical asymptote there.',p=>result(`f(x) = ${p.b}/(x − (${p.a})); x ≠ ${p.a}`,p.a,`Which input is excluded from f(x) = ${p.b}/(x − (${p.a}))?`,['Set the denominator equal to zero.',`x − (${p.a}) = 0 gives x = ${p.a}.`,`Exclude x = ${p.a}; division by zero has no real value.`],{...graphDiagram([x=>p.b/(x-p.a)],[-6,6],[-8,8]),asymptote:p.a,breaks:[p.a]},'The graph is drawn in separate branches, with no line across the excluded input.'));
define('exponential-growth','Exponential growth & decay','algebra2','Compare a constant multiplier with a constant addition.','Powers and percents',[A(1,5,2,'Initial value'),inp('b','Multiplier',.5,2,1.5,.1),C(0,6,3,'Number of periods')],
 'An exponential model multiplies by the same positive factor each period. Factors above 1 grow; factors between 0 and 1 decay.',p=>result(`f(${p.c}) = ${p.a} × ${fmt(p.b)}^${p.c} ≈ ${fmt(p.a*p.b**p.c)}`,p.a*p.b**p.c,`Find ${p.a} × ${fmt(p.b)}^${p.c}.`,[`Start with ${p.a}.`,`Multiply by ${fmt(p.b)} for each of ${p.c} periods.`,`The value is approximately ${fmt(p.a*p.b**p.c)}.`],graphDiagram([x=>p.a*p.b**x],[0,6],[0,Math.max(6,p.a*p.b**6)],[[p.c,p.a*p.b**p.c]]),'The curve extends the discrete-period model to real inputs; use whole periods for period counts.'));
define('logarithms','Logarithms undo exponents','algebra2','Interpret a logarithm as a question about an exponent.','Powers and inverse operations',[A(2,5,2,'Base'),B(-3,4,3,'Exponent')],
 'For a positive base b not equal to 1, log_b(y) is the exponent that makes b raised to that exponent equal y. Real logarithms require y > 0.',p=>result(`log_${p.a}(${fmt(p.a**p.b)}) = ${p.b}`,p.b,`What is log base ${p.a} of ${fmt(p.a**p.b)}?`,[`Ask: ${p.a} raised to what power equals ${fmt(p.a**p.b)}?`,`${p.a}^${p.b} = ${fmt(p.a**p.b)}.`,`Therefore the logarithm is ${p.b}.`],graphDiagram([x=>Math.log(x)/Math.log(p.a)],[.03,8],[-5,4],[[p.a**p.b,p.b]]),'Real logarithms have positive inputs. A highlighted point may lie outside this graph window.'));
define('inverse-functions','Inverse functions','algebra2','Undo a linear rule and reflect its graph across y = x.','Solving linear equations',[A(1,4,2,'Multiplier a'),B(-4,4,1,'Constant b'),C(-3,3,2,'Input x')],
 'An inverse swaps a function’s input and output. For y = ax + b with a nonzero, solve for the original input: x = (y − b)/a.',p=>result(`f(x) = ${p.a}x + (${p.b}); f⁻¹(y) = (y − (${p.b}))/${p.a}`,p.c,`If f(${p.c}) = ${p.a*p.c+p.b}, what is f⁻¹(${p.a*p.c+p.b})?`,[`The forward rule sends ${p.c} to ${p.a*p.c+p.b}.`,`Undo addition: ${p.a*p.c+p.b} − (${p.b}) = ${p.a*p.c}.`,`Undo multiplication: divide by ${p.a} to recover ${p.c}.`],graphDiagram([x=>p.a*x+p.b,x=>(x-p.b)/p.a,x=>x],[-7,7],[-7,7],[[p.c,p.a*p.c+p.b],[p.a*p.c+p.b,p.c]]),'Green: function. Orange: inverse. Dashed gray: y = x. Inverse notation does not mean reciprocal.'));

define('right-triangle-trig','Right-triangle sine & cosine','trig','Relate an acute angle to opposite and adjacent sides.','Right triangles and ratios',[inp('a','Angle θ (degrees)',10,80,35,5),B(2,10,6,'Hypotenuse')],
 'In a right triangle, sin θ = opposite/hypotenuse and cos θ = adjacent/hypotenuse. For a given angle, similar triangles share these ratios.',p=>{const o=p.b*Math.sin(rad(p.a)),adj=p.b*Math.cos(rad(p.a));return result(`opposite = ${p.b} sin(${p.a}°) ≈ ${fmt(o)}`,o,`Find the side opposite ${p.a}° when the hypotenuse is ${p.b}.`,[`Use sin θ = opposite / hypotenuse.`,`Multiply both sides by ${p.b}.`,`opposite = ${p.b} × sin(${p.a}°) ≈ ${fmt(o)}.`],shapeDiagram('rightTrig',{a:adj,b:o,c:p.b,angle:p.a}),'The marked angle is at the left. “Opposite” depends on which acute angle you choose.');});
define('unit-circle','The unit circle','trig','Read cosine and sine as coordinates on a radius-one circle.','Coordinates, right triangles and angle measure',[inp('a','Angle (degrees)',0,360,45,5)],
 'On the unit circle, the point at angle θ counterclockwise from the positive x-axis is (cos θ, sin θ). Coordinate signs follow the quadrant.',p=>result(`P = (cos ${p.a}°, sin ${p.a}°) ≈ (${fmt(Math.cos(rad(p.a)))}, ${fmt(Math.sin(rad(p.a)))})`,Math.sin(rad(p.a)),`What is sin(${p.a}°)?`,['Start on the positive x-axis and turn counterclockwise.',`The point has x = cos θ and y = sin θ.`,`Its y-coordinate is approximately ${fmt(Math.sin(rad(p.a)))}.`],{type:'unitCircle',angle:p.a},'The radius is 1. Horizontal projection: cosine; vertical projection: sine.'));
define('radians','Radians & degrees','trig','Interpret radians as arc length divided by radius.','Circumference and fractions',[inp('a','Angle (degrees)',0,360,120,15)],
 'One radian subtends an arc whose length equals the radius. A full circle has angle 2π radians, so degrees convert by multiplying by π/180.',p=>result(`${p.a}° = ${frac(p.a,180)}π rad ≈ ${fmt(rad(p.a))} rad`,rad(p.a),`Convert ${p.a}° to radians.`,[`A full turn is 360° = 2π radians.`,`Multiply ${p.a} by π/180.`,`The angle is ${frac(p.a,180)}π ≈ ${fmt(rad(p.a))} radians.`],{type:'unitCircle',angle:p.a},'On the unit circle, the highlighted arc length equals the angle in radians.'));
define('sine-waves','Amplitude & period','trig','Change the height and frequency of a sine wave.','Sine, radians and function graphs',[inp('a','Amplitude A',.5,3,2,.5),inp('b','Frequency factor B',.5,3,1,.5)],
 'In y = A sin(Bx), the amplitude is |A|. One cycle occurs when Bx changes by 2π, so the period is 2π/|B|.',p=>result(`y = ${fmt(p.a)} sin(${fmt(p.b)}x); period ≈ ${fmt(2*Math.PI/p.b)}`,2*Math.PI/p.b,`What is the period of y = ${fmt(p.a)} sin(${fmt(p.b)}x)?`,['A sine cycle corresponds to an argument change of 2π.',`Solve B × period = 2π with B = ${fmt(p.b)}.`,`The period is 2π/${fmt(p.b)} ≈ ${fmt(2*Math.PI/p.b)}.`],graphDiagram([x=>p.a*Math.sin(p.b*x)],[0,4*Math.PI],[-4,4]),'Horizontal axis: x in radians. Vertical axis: y. Two standard 2π intervals are shown.'));
define('cosine-law','The law of cosines','trig','Find a side using two sides and their included angle.','Pythagorean theorem and cosine',[A(2,8,5,'Side a'),B(2,8,6,'Side b'),inp('c','Included angle C (degrees)',20,150,60,5)],
 'For two sides a and b enclosing angle C, the opposite side satisfies c² = a² + b² − 2ab cos C. At C = 90°, this becomes the Pythagorean theorem.',p=>{const v=Math.sqrt(p.a*p.a+p.b*p.b-2*p.a*p.b*Math.cos(rad(p.c)));return result(`c² = a² + b² − 2ab cos C; c ≈ ${fmt(v)}`,v,`Find the side opposite ${p.c}° when the two adjacent sides are ${p.a} and ${p.b}.`,['Use c² = a² + b² − 2ab cos C.',`Substitute ${p.a}² + ${p.b}² − 2(${p.a})(${p.b})cos(${p.c}°).`,`Take the positive square root: c ≈ ${fmt(v)}.`],shapeDiagram('cosineTriangle',{a:p.a,b:p.b,c:p.c}),'The selected angle is the included angle between the two known sides.');});
define('trig-identity','Why sin²θ + cos²θ = 1','trig','Connect the fundamental trigonometric identity to a unit-radius right triangle.','Unit circle and Pythagorean theorem',[inp('a','Angle (degrees)',0,360,60,5)],
 'The coordinates (cos θ, sin θ) lie on a circle of radius 1. The Pythagorean theorem gives cos²θ + sin²θ = 1 for every real angle.',p=>result(`sin²(${p.a}°) + cos²(${p.a}°) = 1`,1,`Evaluate sin²(${p.a}°) + cos²(${p.a}°).`,['The horizontal and vertical coordinates are cosine and sine.',`Their squares are ${fmt(Math.cos(rad(p.a))**2)} and ${fmt(Math.sin(rad(p.a))**2)}.`,`The radius squared is 1², so the sum is 1.`],{type:'unitCircle',angle:p.a},'Squaring removes the sign of each coordinate. The identity holds in all quadrants.'));
define('vector-components','Vector components & magnitude','trig','Separate a displacement into horizontal and vertical components.','Coordinates and the Pythagorean theorem',[A(-5,5,3,'Horizontal component'),B(-5,5,4,'Vertical component')],
 'A vector describes both direction and magnitude. Its magnitude is the distance from its tail to its tip, found using its perpendicular components.',p=>result(`|v| = √(${p.a}² + ${p.b}²) ≈ ${fmt(Math.hypot(p.a,p.b))}`,Math.hypot(p.a,p.b),`Find the magnitude of vector ⟨${p.a}, ${p.b}⟩.`,[`Square the components: ${p.a*p.a} and ${p.b*p.b}.`,`Add to get ${p.a*p.a+p.b*p.b}.`,`Take the nonnegative square root: ${fmt(Math.hypot(p.a,p.b))}.`],{...graphDiagram([],[-6,6],[-6,6],[[p.a,p.b]]),vector:[p.a,p.b]},'The arrow gives direction; its length gives magnitude. The zero vector has magnitude zero.'));

const median=data=>{const d=[...data].sort((a,b)=>a-b),m=Math.floor(d.length/2);return d.length%2?d[m]:(d[m-1]+d[m])/2;};
const dataValues=p=>[2,3,4,5,p.a];
define('mean-median','Mean, median & outliers','stats','Compare a balance-point average with a middle-position average.','Addition, ordering and division',[A(0,20,6,'Movable data value')],
 'The mean shares the total equally among all observations. The median is the middle observation after sorting. Moving an extreme value often changes the mean more than the median.',p=>{const d=dataValues(p),mean=d.reduce((s,x)=>s+x,0)/d.length;return result(`mean = ${fmt(mean)}; median = ${median(d)}`,mean,`Find the mean of ${d.join(', ')}.`,[`Add all observations: ${d.reduce((s,x)=>s+x,0)}.`,`There are ${d.length} observations.`,`Divide to get mean ${fmt(mean)}. Sorted middle: ${median(d)}.`],{type:'dotplot',values:d,mean,median:median(d)},'Repeated values stack. The green marker is the mean; orange is the median.');});
define('range-variation','Range & variation','stats','Measure the gap between the largest and smallest observations.','Ordering numbers and subtraction',[A(0,20,9,'Movable data value')],
 'The range is maximum minus minimum. It describes total spread but uses only two observations, so it is sensitive to extremes.',p=>{const d=dataValues(p),v=Math.max(...d)-Math.min(...d);return result(`range = ${Math.max(...d)} − ${Math.min(...d)} = ${v}`,v,`Find the range of ${d.join(', ')}.`,[`The minimum is ${Math.min(...d)}.`,`The maximum is ${Math.max(...d)}.`,`Subtract: range = ${v}.`],{type:'dotplot',values:d},'Range describes spread, not a typical value or the number of observations.');});
define('boxplots','Quartiles & box plots','stats','Read the middle half of a data set using quartiles.','Median and ordered data',[A(9,20,12,'Largest value')],
 'A box plot shows a five-number summary. This lesson uses the median-of-halves convention, excluding the overall median from each half.',p=>{const d=[1,2,3,4,5,6,7,8,p.a],q1=2.5,q3=7.5;return result(`Q₁ = ${q1}, median = 5, Q₃ = ${q3}; IQR = 5`,q3-q1,`For ${d.join(', ')}, what is the interquartile range under the median-of-halves convention?`,['Exclude the median 5 and split the remaining values into two halves.',`The lower-half median is ${q1}; the upper-half median is ${q3}.`,`IQR = Q₃ − Q₁ = 5.`],{type:'boxplot',min:1,q1,med:5,q3,max:p.a},'Whiskers here run to the minimum and maximum; this is not the 1.5×IQR outlier-whisker convention.');});
define('standard-deviation','Standard deviation','stats','Measure typical distance from a mean using squared deviations.','Mean, squares and square roots',[A(1,5,2,'Distance d from the mean'),B(3,10,6,'Mean μ')],
 'Population standard deviation is the square root of the mean squared deviation from μ. Squaring prevents positive and negative deviations from canceling.',p=>{const d=[p.b-p.a,p.b,p.b+p.a],sd=Math.sqrt(2*p.a*p.a/3);return result(`μ = ${p.b}; σ = √(2d²/3) ≈ ${fmt(sd)}`,sd,`Find the population standard deviation of ${d.join(', ')}.`,[`The mean is ${p.b}; deviations are ${-p.a}, 0, ${p.a}.`,`Mean squared deviation = (${p.a*p.a} + 0 + ${p.a*p.a})/3.`,`Take the square root: σ ≈ ${fmt(sd)}.`],{type:'dotplot',values:d,mean:p.b},'The formula divides by N for a population. A sample estimate typically divides by n − 1 instead.');});
define('theoretical-probability','Probability as a fraction','stats','Compare favorable outcomes with equally likely outcomes.','Fractions and ratios',[A(1,6,3,'Green tokens'),B(1,6,2,'Orange tokens')],
 'With equally likely outcomes, probability is favorable outcomes divided by total outcomes. This model draws one token uniformly from a bag.',p=>result(`P(green) = ${p.a}/${p.a+p.b} = ${fmt(p.a/(p.a+p.b))}`,p.a/(p.a+p.b),`What is the probability of drawing green from ${p.a} green and ${p.b} orange tokens?`,[`There are ${p.a+p.b} equally likely tokens.`,`${p.a} tokens are green.`,`Divide favorable by total: ${p.a}/${p.a+p.b} ≈ ${fmt(p.a/(p.a+p.b))}.`],{type:'tokens',a:p.a,b:p.b},'A single random draw gives each token the same chance. Green and orange are also distinguished by letters.'));
define('independent-events','Independent events','stats','Multiply probabilities when one event does not change the other.','Fractions and multiplication',[A(1,5,3,'Green tokens out of 6'),B(1,5,2,'Blue tokens out of 6')],
 'Independent events satisfy P(A and B) = P(A)P(B). Drawing once from each of two separate bags makes the two outcomes independent.',p=>result(`P(both) = (${p.a}/6)(${p.b}/6) = ${p.a*p.b}/36`,p.a*p.b/36,`A green token has chance ${p.a}/6 in bag A; blue has chance ${p.b}/6 in bag B. What is the chance of both?`,['The two draws come from separate bags, so neither changes the other.',`Multiply ${p.a}/6 by ${p.b}/6.`,`The joint probability is ${p.a*p.b}/36 ≈ ${fmt(p.a*p.b/36)}.`],{type:'fractionGrid',cols:6,rows:6,a:p.a,b:p.b},'Rows and columns encode the two independent draws; their overlap encodes joint success.'));
define('conditional-probability','Conditional probability','stats','Restrict the sample space before calculating a probability.','Ratios and two-way tables',[A(1,9,6,'Athletes who take music'),B(1,9,4,'Athletes without music'),C(1,9,3,'Non-athletes who take music')],
 'P(Music | Athlete) uses only athletes as the reference group. Conditioning changes the denominator; it is not generally the same as P(Athlete | Music).',p=>result(`P(M | A) = ${p.a}/(${p.a}+${p.b}) = ${fmt(p.a/(p.a+p.b))}`,p.a/(p.a+p.b),`Among athletes, ${p.a} take music and ${p.b} do not. What is P(Music | Athlete)?`,['Restrict attention to the athlete row.',`There are ${p.a+p.b} athletes, of whom ${p.a} take music.`,`The conditional probability is ${p.a}/${p.a+p.b}.`],{type:'twoWay',a:p.a,b:p.b,c:p.c,d:5},'The highlighted athlete row is the conditional sample space. Counts are synthetic.'));
define('counting-combinations','Combinations','stats','Count selections when order does not matter.','Multiplication and factorials',[A(3,8,5,'Available items n'),B(1,3,2,'Items chosen r')],
 'Ordered selections overcount an unordered group r! times. Dividing by r! gives the combination count n!/[r!(n − r)!].',p=>{const r=Math.min(p.b,p.a),v=range(r,i=>p.a-i).reduce((a,b)=>a*b,1)/range(r,i=>i+1).reduce((a,b)=>a*b,1);return result(`C(${p.a}, ${r}) = ${v}`,v,`How many unordered groups of ${r} can be chosen from ${p.a} distinct items?`,[`Count ordered choices: ${range(r,i=>p.a-i).join(' × ')}.`,`Each group appears in ${range(r,i=>i+1).reduce((a,b)=>a*b,1)} orders.`,`Divide to get ${v} distinct groups.`],{type:'combination',n:p.a,r,count:v},'Items are distinct, selection is without replacement, and group order does not matter.');});
define('expected-value','Expected value','stats','Calculate a probability-weighted long-run average.','Probabilities and weighted averages',[A(1,10,6,'Prize for success ($)'),B(1,5,2,'Success faces on a fair die')],
 'Expected value weights each outcome by its probability. It describes a long-run mean, not a guaranteed result of one trial.',p=>result(`E(prize) = $${p.a} × ${p.b}/6 = $${fmt(p.a*p.b/6)}`,p.a*p.b/6,`A game pays $${p.a} on ${p.b} of 6 equally likely outcomes and $0 otherwise. What is the expected prize?`,[`Success has probability ${p.b}/6 and prize $${p.a}.`,`Failure has probability ${6-p.b}/6 and prize $0.`,`Add weighted outcomes: $${fmt(p.a*p.b/6)}.`],{type:'bars',values:[p.a*p.b/6,0],labels:['success contribution','failure contribution']},'This is expected prize before any entry fee. It is not a prediction of the next payout.'));
define('scatter-regression','Scatterplots & linear fits','stats','Compare observed points with a least-squares line.','Coordinates, slope and means',[A(-2,3,1,'Underlying slope'),B(0,5,2,'Noise amount')],
 'A least-squares line minimizes the sum of squared vertical residuals. A fitted association alone does not establish causation.',p=>{const xs=[0,1,2,3,4,5],noise=[1,-1,.5,-.5,-1,1],ys=xs.map((x,i)=>p.a*x+3+noise[i]*p.b),mx=2.5,my=ys.reduce((a,b)=>a+b,0)/6,m=xs.reduce((s,x,i)=>s+(x-mx)*(ys[i]-my),0)/xs.reduce((s,x)=>s+(x-mx)**2,0),b=my-m*mx;return result(`Least-squares line: ŷ = ${fmt(m)}x + (${fmt(b)})`,m,`What is the slope of the displayed least-squares line?`,['Center x and y by subtracting their respective means.',`Compute Σ(x − x̄)(y − ȳ) / Σ(x − x̄)².`,`The slope is ${fmt(m)}; intercept = ȳ − mx̄ = ${fmt(b)}.`],{...graphDiagram([x=>m*x+b],[-1,6],[-12,25],xs.map((x,i)=>[x,ys[i]])),residuals:true},'Synthetic data. Orange segments are residuals measured vertically to the fitted line.');});
define('normal-zscore','Normal models & z-scores','stats','Measure an observation’s distance from a mean in standard deviations.','Mean and standard deviation',[inp('a','Mean μ',20,80,50,5),B(2,15,10,'Standard deviation σ'),inp('c','Observed value x',0,100,65,5)],
 'A z-score standardizes a value: z = (x − μ)/σ. The normal curve is a model for some distributions, not a rule that every data set follows.',p=>{const z=(p.c-p.a)/p.b;return result(`z = (${p.c} − ${p.a})/${p.b} = ${fmt(z)}`,z,`Find the z-score of ${p.c} when μ = ${p.a} and σ = ${p.b}.`,[`Subtract the mean: ${p.c-p.a}.`,`Divide by the standard deviation ${p.b}.`,`The observation is ${fmt(z)} standard deviations from the mean.`],{...graphDiagram([x=>Math.exp(-.5*((x-p.a)/p.b)**2)/(p.b*Math.sqrt(2*Math.PI))],[p.a-4*p.b,p.a+4*p.b],[0,1/(p.b*Math.sqrt(2*Math.PI))*1.2]),vertical:p.c},'Horizontal axis: observation value. Vertical axis: probability density, not point probability.');});

define('arithmetic-sequences','Arithmetic sequences','advanced','Build a discrete pattern with a constant difference.','Linear relationships',[A(-3,6,2,'First term'),B(-3,5,3,'Common difference'),C(1,8,5,'Term number n')],
 'An arithmetic sequence adds the same difference each step. The nth term is a₁ + (n − 1)d because n − 1 steps follow the first term.',p=>result(`a_${p.c} = ${p.a} + (${p.c} − 1)(${p.b}) = ${p.a+(p.c-1)*p.b}`,p.a+(p.c-1)*p.b,`Find term ${p.c} for first term ${p.a} and common difference ${p.b}.`,[`Begin with a₁ = ${p.a}.`,`Take ${p.c-1} steps of size ${p.b}.`,`The term is ${p.a+(p.c-1)*p.b}.`],{type:'sequence',values:range(8,i=>p.a+i*p.b),selected:p.c-1},'Sequences have integer term indices. The points are not joined as a continuous function.'));
define('geometric-sequences','Geometric sequences','advanced','Build a discrete pattern with a constant ratio.','Powers and multiplication',[A(1,4,2,'First term'),inp('b','Common ratio',.5,3,2,.5),C(1,7,4,'Term number n')],
 'A geometric sequence multiplies by the same ratio at each step. Its nth term is a₁rⁿ⁻¹.',p=>result(`a_${p.c} = ${p.a} × ${fmt(p.b)}^${p.c-1} = ${fmt(p.a*p.b**(p.c-1))}`,p.a*p.b**(p.c-1),`Find term ${p.c} for first term ${p.a} and common ratio ${fmt(p.b)}.`,[`Start with ${p.a}.`,`Multiply by ${fmt(p.b)} a total of ${p.c-1} times.`,`The term is ${fmt(p.a*p.b**(p.c-1))}.`],{type:'sequence',values:range(7,i=>p.a*p.b**i),selected:p.c-1},'A constant ratio produces exponential behavior; only integer indices are sequence terms.'));
define('complex-numbers','Complex numbers on a plane','advanced','Interpret real and imaginary parts as perpendicular coordinates.','Coordinates and i² = −1',[A(-5,5,3,'Real part a'),B(-5,5,4,'Imaginary coefficient b')],
 'A complex number a + bi is represented by (a, b) on the complex plane. Its modulus is its distance from zero: √(a² + b²).',p=>result(`z = ${p.a} + (${p.b})i; |z| = ${fmt(Math.hypot(p.a,p.b))}`,Math.hypot(p.a,p.b),`Find the modulus of ${p.a} + (${p.b})i.`,[`Locate real part ${p.a} horizontally and imaginary coefficient ${p.b} vertically.`,`Use the distance formula: |z|² = ${p.a*p.a+p.b*p.b}.`,`The modulus is ${fmt(Math.hypot(p.a,p.b))}.`],{...graphDiagram([],[-6,6],[-6,6],[[p.a,p.b]]),vector:[p.a,p.b],xLabel:'real',yLabel:'imaginary'},'The horizontal axis is real; the vertical axis is the imaginary coefficient.'));
define('limits','Approaching a limit','advanced','Distinguish a nearby trend from the value at the approached input.','Function graphs and fractions',[A(1,5,2,'Approach point h'),inp('b','Distance ε',.01,1,.5,.01)],
 'For f(x) = (x² − h²)/(x − h), x = h is excluded. At other inputs f(x) = x + h, so both sides approach 2h even though the original expression has a hole.',p=>result(`lim[x→${p.a}] (x² − ${p.a*p.a})/(x − ${p.a}) = ${2*p.a}`,2*p.a,`What limit does this function approach as x tends to ${p.a}?`,[`For x ≠ ${p.a}, factor and cancel: (x − ${p.a})(x + ${p.a})/(x − ${p.a}) = x + ${p.a}.`,`At h − ε and h + ε, outputs are ${fmt(2*p.a-p.b)} and ${fmt(2*p.a+p.b)}.`,`As ε tends to zero, both approach ${2*p.a}. The original value at h remains undefined.`],{...graphDiagram([x=>x+p.a],[p.a-2,p.a+2],[2*p.a-3,2*p.a+3],[[p.a-p.b,2*p.a-p.b],[p.a+p.b,2*p.a+p.b]]),hole:[p.a,2*p.a]},'The open circle marks an excluded input. A limit need not equal a defined function value.'));
define('derivatives','From secant to tangent','advanced','Watch average rate of change approach an instantaneous rate.','Slope, functions and limits',[A(-3,3,2,'Location x'),inp('b','Input step h',.01,2,1,.01)],
 'For f(x) = x², the secant slope over step h is [(x + h)² − x²]/h = 2x + h. As h tends to zero, this approaches the derivative 2x.',p=>result(`secant slope = ${fmt(2*p.a+p.b)}; f′(${p.a}) = ${2*p.a}`,2*p.a,`What is the exact derivative of f(x) = x² at x = ${p.a}?`,[`The secant slope is 2x + h = ${fmt(2*p.a+p.b)}.`,`Let h approach zero.`,`The limiting slope is 2x = ${2*p.a}.`],{...graphDiagram([x=>x*x,x=>2*p.a*(x-p.a)+p.a*p.a,x=>(2*p.a+p.b)*(x-p.a)+p.a*p.a],[-5,5],[-8,25],[[p.a,p.a*p.a],[p.a+p.b,(p.a+p.b)**2]]),legend:['x²','tangent','secant']},'Green: x². Orange: tangent. Dashed gray: secant. Decrease h to compare the two slopes.'));
define('integrals','Accumulation & definite integrals','advanced','Compare rectangular estimates with exact signed accumulation.','Area, sums and function graphs',[A(1,5,3,'Upper endpoint b'),B(2,20,6,'Number of right rectangles')],
 'A definite integral is the limit of signed area sums. For f(x) = x on [0, b], the exact area is a triangle of area b²/2.',p=>{const exact=p.a*p.a/2,dx=p.a/p.b,estimate=range(p.b,i=>(i+1)*dx*dx).reduce((a,b)=>a+b,0);return result(`∫₀^${p.a} x dx = ${fmt(exact)}; right sum ≈ ${fmt(estimate)}`,exact,`Find the exact integral of f(x) = x from 0 to ${p.a}.`,[`The region is a right triangle with base ${p.a} and height ${p.a}.`,`Its area is ½ × ${p.a} × ${p.a}.`,`The exact integral is ${fmt(exact)}. Increasing the rectangle count improves the right-sum approximation.`],{...graphDiagram([x=>x],[0,p.a+.5],[0,p.a+.5]),rectangles:{n:p.b,b:p.a}},'Right-endpoint rectangles overestimate this increasing function. The exact answer is the triangle area, not the rectangle sum.');});
